SELECT CAST(COUNT(CASE WHEN p.dod IS NOT NULL THEN 1 END) AS FLOAT) / NULLIF(COUNT(p.subject_id), 0) AS mortality_rate, COUNT(CASE WHEN i.los BETWEEN 1 AND 3 THEN 1 END) AS los_1_3, COUNT(CASE WHEN i.los BETWEEN 4 AND 7 THEN 1 END) AS los_4_7, COUNT(CASE WHEN i.los >= 8 THEN 1 END) AS los_8_plus, COUNT(CASE WHEN c.score BETWEEN 1 AND 4 THEN 1 END) AS charlson_1_4, COUNT(CASE WHEN c.score > 5 THEN 1 END) AS charlson_6_plus, AVG(p.dod - p.admittime) AS average_length_of_stay FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays i ON a.stay_id = i.stay_id JOIN charlson c ON p.subject_id = c.subject_id WHERE p.gender = 'M' AND p.anchor_age = 65 AND a.admission_type = 'postoperative' AND (i.careunit = 'ICU' OR i.careunit = 'CCU') GROUP BY p.subject_id;